import java.util.*;
public class UtilMisc {enum Color { RED,GREEN,BLUE } public static void main(String[] args){EnumSet<Color> s=EnumSet.range(Color.RED,Color.BLUE);s.remove(Color.GREEN);System.out.println(s+" "+EnumSet.complementOf(s));EnumMap<Color,String> m=new EnumMap<>(Color.class);m.put(Color.BLUE,"b");m.put(Color.RED,"r");System.out.println(m);BitSet b=new BitSet();b.set(1);b.set(4,7);b.flip(5);System.out.println(b+" "+b.cardinality()+" "+b.nextClearBit(4));UUID u=UUID.fromString("12345678-1234-5678-9abc-123456789abc");System.out.println(u+" "+u.version()+" "+u.variant());System.out.println(new Date(20).after(new Date(10)));System.out.println(Collections.unmodifiableNavigableSet(new TreeSet<>(Arrays.asList(3,1,2))).descendingSet());}}
